async function roccoUniversalFetchPropsJson(url) {
    if (typeof require !== 'undefined') {
        try {
            const u = new URL(url);
            const client = u.protocol === 'https:' ? require('https') : require('http');
            const port = u.port || (u.protocol === 'https:' ? 443 : 80);
            const res = await new Promise((resolve, reject) => {
                const req = client.request({
                    hostname: u.hostname,
                    port: port,
                    path: u.pathname + u.search,
                    method: 'GET',
                    headers: { 'Accept': 'application/json', 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) Rocco-Extension/3.5' }
                }, (r) => {
                    let d = '';
                    r.on('data', chunk => d += chunk);
                    r.on('end', () => {
                        try { resolve(JSON.parse(d)); } catch(e) { reject(e); }
                    });
                });
                req.on('error', reject);
                req.setTimeout(8000, () => { req.destroy(); reject(new Error('Timeout')); });
                req.end();
            });
            if (res) return res;
        } catch(e) {}
    }
    try {
        const res = await fetch(url, { headers: { 'Accept': 'application/json' } });
        if (res.ok) return await res.json();
    } catch(e) {}
    return null;
}

